import{_ as s,o as n,c as e,ag as t}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":1777882948000}'),l={name:"architecture.md"};function i(p,a,o,r,d,c){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="high-level-overview" tabindex="-1">High-Level Overview <a class="header-anchor" href="#high-level-overview" aria-label="Permalink to &quot;High-Level Overview&quot;">​</a></h2><p>RustChat is composed of three runtime services and four external dependencies:</p><table tabindex="0"><thead><tr><th>Service</th><th>Technology</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Backend</strong></td><td>Rust (Axum 0.8 + Tokio)</td><td>HTTP API, WebSocket hub, business logic</td></tr><tr><td><strong>Frontend</strong></td><td>Vue 3.5 + TypeScript + Pinia</td><td>Single-page web application</td></tr><tr><td><strong>Push Proxy</strong></td><td>Rust (Axum)</td><td>Mobile push notification gateway (FCM / APNS)</td></tr></tbody></table><p><strong>External dependencies:</strong></p><table tabindex="0"><thead><tr><th>Dependency</th><th>Purpose</th><th>Required</th></tr></thead><tbody><tr><td>PostgreSQL 16+</td><td>Primary data store</td><td>Yes</td></tr><tr><td>Redis 7+</td><td>Pub/sub, rate limiting, sessions</td><td>Yes</td></tr><tr><td>S3-compatible storage</td><td>File uploads</td><td>Yes</td></tr><tr><td>FCM / APNS</td><td>Mobile push notifications</td><td>Optional</td></tr><tr><td>SMTP</td><td>Email, password reset</td><td>Optional</td></tr><tr><td>OAuth providers</td><td>SSO login</td><td>Optional</td></tr><tr><td>Meilisearch</td><td>Full-text search</td><td>Optional (via <code>search</code> profile)</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────┐     ┌──────────────────┐     ┌─────────────────┐</span></span>
<span class="line"><span>│   Web Client    │────▶│  RustChat API    │◀────│  Push Proxy     │</span></span>
<span class="line"><span>│  (Vue.js SPA)   │     │  (Rust / Axum)   │     │ (Mobile Push)   │</span></span>
<span class="line"><span>└─────────────────┘     └──────────────────┘     └─────────────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>           ┌───────────────────┼───────────────────┐</span></span>
<span class="line"><span>           ▼                   ▼                   ▼</span></span>
<span class="line"><span>      ┌──────────┐      ┌──────────┐      ┌──────────────┐</span></span>
<span class="line"><span>      │PostgreSQL│      │  Redis   │      │S3-compatible │</span></span>
<span class="line"><span>      │(Primary) │      │(Pub/Sub) │      │(File Store)  │</span></span>
<span class="line"><span>      └──────────┘      └──────────┘      └──────────────┘</span></span></code></pre></div><hr><h2 id="request-flow" tabindex="-1">Request Flow <a class="header-anchor" href="#request-flow" aria-label="Permalink to &quot;Request Flow&quot;">​</a></h2><p>A typical HTTP request flows through these layers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client → Reverse Proxy (optional) → Axum Router → Middleware → Handler → Service → Database/S3/Redis</span></span></code></pre></div><ol><li><strong>Client request</strong> → Reverse proxy (optional, for TLS)</li><li><strong>Axum router</strong> → Matches path to handler</li><li><strong>Middleware</strong> → Auth (JWT validation), rate limiting, CORS, tracing, request ID</li><li><strong>Handler</strong> → Thin HTTP layer, delegates to services</li><li><strong>Service</strong> → Business logic, database queries, external calls</li><li><strong>Response</strong> → Serialized via <code>Result&lt;T, AppError&gt;</code> with consistent JSON error format</li></ol><hr><h2 id="authentication-flow" tabindex="-1">Authentication Flow <a class="header-anchor" href="#authentication-flow" aria-label="Permalink to &quot;Authentication Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────┐    POST /api/v1/auth/login    ┌──────────┐</span></span>
<span class="line"><span>│  Client │ ─────────────────────────────▶│ Backend  │</span></span>
<span class="line"><span>│         │                               │          │</span></span>
<span class="line"><span>│         │◀──────────────────────────────│          │</span></span>
<span class="line"><span>│         │    { access_token, refresh }  │          │</span></span>
<span class="line"><span>│         │                               │          │</span></span>
<span class="line"><span>│         │    WS /api/v1/ws              │          │</span></span>
<span class="line"><span>│         │    Authorization: Bearer ...  │          │</span></span>
<span class="line"><span>│         │ ─────────────────────────────▶│          │</span></span>
<span class="line"><span>│         │                               │          │</span></span>
<span class="line"><span>│         │◀──────────────────────────────│          │</span></span>
<span class="line"><span>│         │    Real-time events           │          │</span></span>
<span class="line"><span>└─────────┘                               └──────────┘</span></span></code></pre></div><ol><li>Client POSTs credentials to <code>/api/v1/auth/login</code></li><li>Backend validates against PostgreSQL, issues JWT access + refresh tokens</li><li>Client includes <code>Authorization: Bearer &lt;token&gt;</code> header on all API requests</li><li>WebSocket connection uses the same token via header (or query param in development)</li><li>Refresh token endpoint (<code>/api/v1/auth/refresh</code>) silently extends sessions</li></ol><hr><h2 id="api-surface" tabindex="-1">API Surface <a class="header-anchor" href="#api-surface" aria-label="Permalink to &quot;API Surface&quot;">​</a></h2><p>The backend exposes two API versions on the same HTTP server:</p><table tabindex="0"><thead><tr><th>API</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Native</strong></td><td><code>/api/v1/*</code></td><td>Web client, modern features</td></tr><tr><td><strong>Compatible</strong></td><td><code>/api/v4/*</code></td><td>Mattermost-compatible for mobile/desktop clients</td></tr></tbody></table><p>Both share the same service layer and database. The v4 layer translates request/response formats to match Mattermost&#39;s API contract.</p><hr><h2 id="real-time-communication" tabindex="-1">Real-Time Communication <a class="header-anchor" href="#real-time-communication" aria-label="Permalink to &quot;Real-Time Communication&quot;">​</a></h2><p>Two WebSocket endpoints share a common event core:</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Format</th><th>Clients</th></tr></thead><tbody><tr><td><code>/api/v1/ws</code></td><td>Internal envelope</td><td>Web app</td></tr><tr><td><code>/api/v4/websocket</code></td><td>Mattermost framing</td><td>Mobile apps, desktop clients</td></tr></tbody></table><h3 id="websocket-event-flow" tabindex="-1">WebSocket Event Flow <a class="header-anchor" href="#websocket-event-flow" aria-label="Permalink to &quot;WebSocket Event Flow&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────┐     WS connection      ┌──────────┐</span></span>
<span class="line"><span>│ Client A│◀──────────────────────▶│ Backend 1│</span></span>
<span class="line"><span>│         │                        │          │</span></span>
<span class="line"><span>│         │                        │  Redis   │</span></span>
<span class="line"><span>│         │                        │  pub/sub │</span></span>
<span class="line"><span>│         │                        │          │</span></span>
<span class="line"><span>│ Client B│◀──────────────────────▶│ Backend 2│</span></span>
<span class="line"><span>└─────────┘                        └──────────┘</span></span></code></pre></div><ol><li>Client A sends a message via WebSocket to Backend 1</li><li>Backend 1 persists to PostgreSQL</li><li>Backend 1 publishes event to Redis pub/sub channel</li><li>Backend 2 (and any other instances) receives the event from Redis</li><li>Backend 2 forwards the event to connected clients (including Client B)</li></ol><p>This design allows horizontal scaling: add more backend instances behind a load balancer, and Redis coordinates real-time delivery across all of them.</p><hr><h2 id="file-upload-flow" tabindex="-1">File Upload Flow <a class="header-anchor" href="#file-upload-flow" aria-label="Permalink to &quot;File Upload Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────┐    POST /api/v1/files    ┌──────────┐    PUT      ┌─────────┐</span></span>
<span class="line"><span>│  Client │ ───────────────────────▶│ Backend  │ ──────────▶│   S3    │</span></span>
<span class="line"><span>│         │  multipart/form-data    │          │  presigned │ (RustFS)│</span></span>
<span class="line"><span>│         │                         │          │  URL       │         │</span></span>
<span class="line"><span>│         │◀─────────────────────── │          │◀───────────│         │</span></span>
<span class="line"><span>│         │  { file_id, url }       │          │            │         │</span></span>
<span class="line"><span>│         │                         │          │            │         │</span></span>
<span class="line"><span>│         │    GET /api/v1/files/...│          │            │         │</span></span>
<span class="line"><span>│         │ ───────────────────────▶│          │            │         │</span></span>
<span class="line"><span>│         │                         │          │  proxy     │         │</span></span>
<span class="line"><span>│         │◀─────────────────────── │          │◀───────────│         │</span></span>
<span class="line"><span>│         │  file bytes (auth&#39;d)    │          │            │         │</span></span>
<span class="line"><span>└─────────┘                         └──────────┘            └─────────┘</span></span></code></pre></div><ol><li>Client uploads file via multipart POST to backend</li><li>Backend generates a presigned URL and uploads to S3-compatible storage</li><li>Backend returns file metadata to client</li><li>Client requests file download through backend (authenticated)</li><li>Backend proxies the file from S3 with auth check — no presigned URL leaks to end users</li></ol><hr><h2 id="deployment-topology" tabindex="-1">Deployment Topology <a class="header-anchor" href="#deployment-topology" aria-label="Permalink to &quot;Deployment Topology&quot;">​</a></h2><h3 id="single-node-evaluation-small-team" tabindex="-1">Single-Node (Evaluation / Small Team) <a class="header-anchor" href="#single-node-evaluation-small-team" aria-label="Permalink to &quot;Single-Node (Evaluation / Small Team)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                 Single Host                  │</span></span>
<span class="line"><span>│  ┌─────────┐  ┌─────────┐  ┌─────────────┐ │</span></span>
<span class="line"><span>│  │ Nginx   │  │Backend  │  │Frontend     │ │</span></span>
<span class="line"><span>│  │(TLS)    │  │(Port   │  │(Port 8080)  │ │</span></span>
<span class="line"><span>│  │(443)    │  │ 3000)   │  │             │ │</span></span>
<span class="line"><span>│  └────┬────┘  └────┬────┘  └─────────────┘ │</span></span>
<span class="line"><span>│       │            │                        │</span></span>
<span class="line"><span>│       └────────────┘                        │</span></span>
<span class="line"><span>│  ┌─────────┐  ┌─────────┐  ┌─────────────┐ │</span></span>
<span class="line"><span>│  │PostgreSQL│  │  Redis  │  │S3 (RustFS)  │ │</span></span>
<span class="line"><span>│  │(Port   │  │(Port   │  │(Port 9000)   │ │</span></span>
<span class="line"><span>│  │ 5432)   │  │ 6379)   │  │             │ │</span></span>
<span class="line"><span>│  └─────────┘  └─────────┘  └─────────────┘ │</span></span>
<span class="line"><span>└─────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="multi-node-production" tabindex="-1">Multi-Node (Production) <a class="header-anchor" href="#multi-node-production" aria-label="Permalink to &quot;Multi-Node (Production)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                        ┌─────────────┐</span></span>
<span class="line"><span>                        │  Load Balancer│</span></span>
<span class="line"><span>                        │   (TLS)       │</span></span>
<span class="line"><span>                        └──────┬──────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>              ┌────────────────┼────────────────┐</span></span>
<span class="line"><span>              ▼                ▼                ▼</span></span>
<span class="line"><span>        ┌──────────┐     ┌──────────┐     ┌──────────┐</span></span>
<span class="line"><span>        │ Backend 1│     │ Backend 2│     │ Backend N│</span></span>
<span class="line"><span>        │          │◄───►│          │◄───►│          │</span></span>
<span class="line"><span>        └────┬─────┘     └────┬─────┘     └────┬─────┘</span></span>
<span class="line"><span>             │                │                │</span></span>
<span class="line"><span>             └────────────────┼────────────────┘</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>                    ┌─────────┴─────────┐</span></span>
<span class="line"><span>                    ▼                   ▼</span></span>
<span class="line"><span>              ┌──────────┐        ┌──────────┐</span></span>
<span class="line"><span>              │ PostgreSQL│        │  Redis   │</span></span>
<span class="line"><span>              │  (HA)     │        │ (Cluster)│</span></span>
<span class="line"><span>              └──────────┘        └──────────┘</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    ▼</span></span>
<span class="line"><span>              ┌──────────┐</span></span>
<span class="line"><span>              │S3 (Cloud) │</span></span>
<span class="line"><span>              └──────────┘</span></span></code></pre></div><p><strong>Key differences:</strong></p><ul><li>Load balancer distributes HTTP traffic (sticky sessions recommended for WebSocket)</li><li>Redis pub/sub synchronizes real-time events across backend instances</li><li>PostgreSQL and S3 are shared external services</li><li>Frontend is a static SPA that can be served by CDN or any static file server</li></ul><hr><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><ul><li><a href="./architecture/overview">Architecture Overview (detailed)</a></li><li><a href="./architecture/backend">Backend Architecture</a></li><li><a href="./architecture/frontend">Frontend Architecture</a></li><li><a href="./architecture/data-model">Data Model</a></li><li><a href="./architecture/websocket">WebSocket Design</a></li><li><a href="./architecture/calls-deployment">Calls Deployment</a></li></ul>`,44)])])}const b=s(l,[["render",i]]);export{u as __pageData,b as default};
